{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Vismodegib, the closest analogue sharing the methylsulfonylphenyl, chlorophenyl, and pyridine motifs, has a mean absolute oral bioavailability of 31.8% in healthy subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Rofecoxib, a methylsulfonylphenyl-containing drug, has an absolute oral bioavailability of 93% in humans, supporting high F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Valdecoxib, a heteroaryl methylsulfonamide with similar lipophilic aromatic character, has an absolute bioavailability of 83% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Esaxerenone, which contains a methylsulfonylphenyl group, shows approximately 89% absolute oral bioavailability in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "5-Hydroxyrofecoxib, a polar hydroxylated metabolite, has low oral bioavailability (~14-15%), but its extra hydroxyl/lactone and metabolite status make it a poor transfer model for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic heterobiaryl methylsulfone. The closest analogue vismodegib has absolute F=31.8%, and multiple methylsulfonyl/heteroaryl drugs (rofecoxib 93%, valdecoxib 83%, esaxerenone ~90%) are highly orally bioavailable. The only low-F analogue is a polar hydroxylated metabolite with limited transferability. Thus F>=20% is supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule.",
    "All retrieved analogues have Morgan similarity below 0.3, limiting quantitative transfer.",
    "No experimental data on solubility, permeability, or first-pass metabolism specific to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

